import{_ as r,a0 as i,w as h,s as l,ao as s,I as p,x as e,a1 as a,A as o}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const T=JSON.parse(`{"title":"Cheat—— 給Linux初學者和管理員一個終極命令列‘備忘單’ | LCTT x X-CMD","titleTemplate":false,"description":"Cheat—— 給Linux初學者和管理員一個終極命令列‘備忘單’ | LCTT (201409) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Cheat—— 給Linux初學者和管理員一個終極命令列‘備忘單’ | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Cheat—— 給Linux初學者和管理員一個終極命令列‘備忘單’ | LCTT (201409) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201409/20140804 Cheat--An Ultimate Command Line 'Cheat-Sheet' for Linux Beginners and Administrators","title":"Cheat—— 給Linux初學者和管理員一個終極命令列‘備忘單’","tag":"201409","desc":""},"relativePath":"201409/20140804 Cheat--An Ultimate Command Line 'Cheat-Sheet' for Linux Beginners and Administrators.md","filePath":"[post].md"}`),c={name:"201409/20140804 Cheat--An Ultimate Command Line 'Cheat-Sheet' for Linux Beginners and Administrators.md"};function m(d,t,g,u,w,C){const n=i("Link");return h(),l("div",null,[t[16]||(t[16]=s(`<h1 id="cheat——-給linux初學者和管理員一個終極命令列-備忘單" tabindex="-1">Cheat—— 給Linux初學者和管理員一個終極命令列‘備忘單’ <a class="header-anchor" href="#cheat——-給linux初學者和管理員一個終極命令列-備忘單" aria-label="Permalink to “Cheat—— 給Linux初學者和管理員一個終極命令列‘備忘單’”">​</a></h1><p>當你不確定你所運行的命令，尤其是那些使用了許多選項的複雜命令時，你會怎麼做？在這種情況下，我們使用man pages來獲取幫助。還有一些其它的選擇可能包括像‘<strong>help</strong>’，‘<strong>whereis</strong>’和‘<strong>whatis</strong>’這樣的命令。但是所有的這些既有優點，也有缺點。</p><p>當我們瀏覽<strong>man pages</strong>來查看選項和幫助的時候，裏面的描述實在太冗長了，我們無法在短的時間裏理解它的意思。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/Linux-Man-Pages.jpeg" alt="Linux Man Pages"> Linux Man Pages</p><p>同樣，‘<strong>help</strong>’命令可能也不會給你期待的答案。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/help-command.jpeg" alt="Help Command"> Help Command</p><p>‘<strong>whereis</strong>’命令幾乎不給你任何信息，除了安裝二進制文件的位置（有些時候可能是重要的）</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/whereis-command.jpeg" alt="Whereis Command"> Whereis Command</p><p>‘<strong>whatis</strong>’命令給出一套很嚴格的答案，它除了説出所查詢命令的作用，並沒有什麼太大幫助。而且，它從來不説明可用的選項。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/whatis-command.jpeg" alt="Whatis Command"> Whatis Command</p><p>直到在困難中解決問題前，我們已經使用了以上全部選項，但是現在來了一個交互式的備忘錄應用程序‘<strong>cheat</strong>’，它將在其餘的命令中脱穎而出。</p><h3 id="什麼是cheat" tabindex="-1">什麼是cheat? <a class="header-anchor" href="#什麼是cheat" aria-label="Permalink to “什麼是cheat?”">​</a></h3><p><strong>cheat</strong>是在GNU通用公共許可證下，為Linux命令列用户發行的交互式備忘單應用程序。它提供顯示Linux命令使用案例，包括該命令所有的選項和簡短但尚可理解的功能。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/cheat-sheet.jpeg" alt="Cheat: Provides Easy Command Options"></p><p>Cheat：提供簡單命令選項</p><h3 id="在linux系統中安裝-cheat" tabindex="-1">在Linux系統中安裝‘Cheat’ <a class="header-anchor" href="#在linux系統中安裝-cheat" aria-label="Permalink to “在Linux系統中安裝‘Cheat’”">​</a></h3><p>‘<strong>Cheat</strong>’有兩個主要的依賴——‘<strong>python</strong>’ 和 ‘<strong>pip</strong>’，在安裝‘<strong>cheat</strong>’之前，確保你的系統安裝了python和pip。</p><h3 id="install-python" tabindex="-1">Install Python <a class="header-anchor" href="#install-python" aria-label="Permalink to “Install Python”">​</a></h3><pre><code># apt-get install Python (基於Debian的系統)
# yum install python (基於小紅帽的系統)
</code></pre><p>Install Pip</p><pre><code># apt-get install python-pip (基於Debian的系統)
# yum install python-pip (基於小紅帽的系統)
</code></pre><p><strong>Note</strong>：pip是一個簡單的安裝替代，是一個有極大改進的Python第三方包安裝器。</p><h3 id="下載並安裝cheat" tabindex="-1">下載並安裝Cheat <a class="header-anchor" href="#下載並安裝cheat" aria-label="Permalink to “下載並安裝Cheat”">​</a></h3><p>我們將通過Git下載‘Cheat’，確保你安裝了‘git’包，如果沒有最好安裝一下。</p><pre><code># apt-get install git (基於Debian的系統)
# yum install git (基於小紅帽的系統)
</code></pre><p>接下來，通過運行下面的命令來安裝所需要的python依賴包。</p><pre><code># pip install docopt pygments
</code></pre>`,27)),p("p",null,[t[1]||(t[1]=e("現在，複製cheat的",-1)),a(n,{href:"http://www.tecmint.com/install-git-to-create-and-share-your-own-projects-on-github-repository/"},{default:o(()=>[...t[0]||(t[0]=[e("Git庫",-1)])]),_:1})]),t[17]||(t[17]=s(`<pre><code># git clone https://github.com/chrisallenlane/cheat.git
</code></pre><p>進入cheat目錄，運行‘<strong>setup.py</strong>’（一個python腳本）。</p><pre><code># cd cheat
# python setup.py install
</code></pre><p>如果安裝很順利，你就能夠看到安裝在系統上的cheat版本了。</p><pre><code># cheat -v
cheat 2.0.9
</code></pre><h3 id="cheat的一些必要配置" tabindex="-1">cheat的一些必要配置 <a class="header-anchor" href="#cheat的一些必要配置" aria-label="Permalink to “cheat的一些必要配置”">​</a></h3><p>你必須在‘~/.bashrc’文件裏設置‘<strong>EDITOR</strong>’環境變量，打開用户‘<strong>.bashrc</strong>’文件，然後把下面這行加入到裏面：</p><pre><code>export EDITOR = /usr/bin/nano
</code></pre><p>你可以使用你喜歡的編輯器來替代‘<strong>nano</strong>’。保存文件然後退出，再次登錄以確保修改生效。</p><p>接下來，添加cheat的自動補全特性，來確保不同解釋器下命令列的自動補全。為了到達該功能要求，簡單地將‘<strong>cheat.bash</strong>’腳本clone下來，然後複製到你係統正確的路徑下。</p><pre><code># wget https://github.com/chrisallenlane/cheat/raw/master/cheat/autocompletion/cheat.bash 
# mv cheat.bash /etc/bash_completion.d/
</code></pre><p><strong>NOTE</strong>：團隊已經在Git上上傳了其他解釋器的自動補全腳本，這些都可以被克隆，然後用在不同的解釋器上。使用下面的鏈接，以找到其餘解釋器的自動補全腳本：</p>`,12)),p("ul",null,[p("li",null,[a(n,{href:"https://github.com/chrisallenlane/cheat/tree/master/cheat/autocompletion"},{default:o(()=>[...t[2]||(t[2]=[e("Auto Completion Script for Various Shells",-1)])]),_:1})])]),t[18]||(t[18]=s(`<p>不僅如此，如果需要的話，你也可以使用語法高亮。要想做到這一點，在你的‘<strong>.bashrc</strong>’文件中添加‘<strong>CHEATCOLORS</strong>’環境變量。</p><pre><code>export CHEATCOLOR=true
</code></pre><p>Cheat應用默認只提供最基本和最常用的命令。cheat備忘單的內容保存在<strong>~/.cheat/.</strong>目錄裏，我們可以手動在這個目錄添加備忘單裏面的內容，這樣，我們的cheat應用將更強大。</p><pre><code># cheat -xyz
</code></pre><p>這將打開xyz備忘單，如果沒有的話就會創建一個。備忘單將使用<strong>.bashrc</strong>裏設置的默認<strong>編輯器</strong>打開，默認編輯器就是在上面<strong>.bashrc</strong>所設置的。</p><h3 id="一些cheat命令的使用" tabindex="-1">一些Cheat命令的使用 <a class="header-anchor" href="#一些cheat命令的使用" aria-label="Permalink to “一些Cheat命令的使用”">​</a></h3><p>一個包可以是 *.gz , *.bz2 , *.zip , *.xz，可是什麼情況下用哪些選項呢？</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/cheat-tar.jpeg" alt="tar command options"> tar命令選項</p><p>除非在不同的地方諮詢和核對後，我才使用<strong>dd</strong>命令，在此之前，無論我對這個命令多麼的肯定，我從不使用它。現在，事情就變得簡單多了。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/cheat-dd.jpeg" alt="dd command options"> dd命令選項</p><p>‘<strong>uname</strong>’命令幫助</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/uname-command.jpeg" alt="uname command options"> uname命令選擇</p><p>一個簡短的<strong>ifconfig</strong>命令操作教程</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/ifconfig-command.jpeg" alt="ifconfig command options"> ifconfig命令選項</p><p>‘top’命令，對管理員和普通用户來説，是最重要的命令之一。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/top-command.jpeg" alt="top command options"> top命令選項</p><p>我們來騙騙cheat命令，如何（儘管別有意義）？得到一個可用命令的列表，其實就是安裝在你係統裏的cheat備忘錄。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/linux-commands.jpeg" alt="List All Linux Commands"> 列出所有Linux命令</p><p>使用關鍵字搜索備忘單。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/search-cheat-sheet.jpeg" alt="Search Cheat Sheet"> 搜索備忘單</p><p>來看看包含所有命令的內置備忘單。</p><pre><code>$ cheat -d

/home/avi/.cheat
/usr/local/lib/python2.7/dist-packages/cheat/cheatsheets
</code></pre><p>複製內置的備忘單到你的本地目錄。</p><pre><code># cp /usr/local/lib/python2.7/dist-packages/cheat/cheatsheets/* /home/avi/.cheat/
</code></pre><h3 id="結論" tabindex="-1">結論 <a class="header-anchor" href="#結論" aria-label="Permalink to “結論”">​</a></h3><p>這個超棒的工具在許多情況下擔任“救世主”的角色，它給予你需要的信息，信息不冗餘，不模糊，相反地，卻擊中要點。這是每個人都會需要的工具，很簡單就能創建、安裝，使用和理解，這個工具前途無量。</p><p>這個Git倉庫已經添加了一個精彩的<strong>gag</strong>，這裏我不打算去解釋它，而留給各位來解釋。</p><p><img src="http://www.tecmint.com/wp-content/uploads/2014/07/linux-gag.jpeg" alt="Linux Gag"> Linux Gag</p><p>好了，文章就要結束了，我會帶着下一篇你們喜歡的有趣文章回到這裏的，在此之前，要時刻關注我們。別忘了在下面的評論部分給我們留下您寶貴的反饋信息。</p><hr>`,30)),p("p",null,[t[4]||(t[4]=e("via: ",-1)),a(n,{href:"http://www.tecmint.com/cheat-command-line-cheat-sheet-for-linux-users/"},{default:o(()=>[...t[3]||(t[3]=[e("http://www.tecmint.com/cheat-command-line-cheat-sheet-for-linux-users/",-1)])]),_:1})]),p("p",null,[t[8]||(t[8]=e("作者：",-1)),a(n,{href:"http://www.tecmint.com/author/avishek/"},{default:o(()=>[...t[5]||(t[5]=[e("Avishek Kumar",-1)])]),_:1}),t[9]||(t[9]=e(" 譯者：",-1)),a(n,{href:"https://github.com/su-kaiyao"},{default:o(()=>[...t[6]||(t[6]=[e("su-kaiyao",-1)])]),_:1}),t[10]||(t[10]=e(" 校對：",-1)),a(n,{href:"https://github.com/carolinewuyan"},{default:o(()=>[...t[7]||(t[7]=[e("Caroline",-1)])]),_:1})]),p("p",null,[t[13]||(t[13]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:o(()=>[...t[11]||(t[11]=[e("LCTT",-1)])]),_:1}),t[14]||(t[14]=e(" 原創翻譯，",-1)),a(n,{href:"http://linux.cn/"},{default:o(()=>[...t[12]||(t[12]=[e("Linux中國",-1)])]),_:1}),t[15]||(t[15]=e(" 榮譽推出",-1))])])}const b=r(c,[["render",m]]);export{T as __pageData,b as default};
